import{z as A,x as d,o as t,c as p,q as i,j as n,D as e,d as E,s as l,S as o,b as s}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"AES 结构","description":"","frontmatter":{"title":"AES 结构","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/aes-structure.md","filePath":"cs/aes-structure.md","lastUpdated":1791063341000}'),S={name:"cs/aes-structure.md"};function m(B,a,u,h,c,D){const r=d("Mermaid");return t(),p("div",null,[a[2]||(a[2]=i('<h1 id="aes-结构" tabindex="-1">AES 结构 <a class="header-anchor" href="#aes-结构" aria-label="Permalink to &quot;AES 结构&quot;">​</a></h1><div class="epigraph"><p>AES 是 128 比特块上的代换–置换网络：字节代换、行移位、列混合、加轮密钥。它是候选伪随机置换，不是一次一密，也不是「公开算法就不安全」。</p><footer>—— Daemen and Rijmen, The Design of Rijndael；NIST FIPS 197</footer></div><p>上一课<a href="/cs/prg-prf">PRG 与 PRF</a>给出计算安全的函数合同。缺口是<strong>实践里那张置换表从哪来</strong>。主干<a href="/cs/symmetric-crypto">对称加密</a>已用 AES 当名字；本课只补结构：SPN、圈数与密钥宽，不把侧信道当本课主轴。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PRF 课留下「候选」。Rijndael 被定为 AES：状态 4×4 字节，SubBytes 用有限域逆，ShiftRows 扩散位置，MixColumns 在 $ \\mathrm{GF}(2^8) $ 上混列，AddRoundKey 异或轮密钥。缺口是理解为何这是 SPN 而不是 Feistel——后课才对照 DES。不要把圈数口算成「安全比特」。</p><h3 id="公开算法" tabindex="-1">公开算法 <a class="header-anchor" href="#公开算法" aria-label="Permalink to &quot;公开算法&quot;">​</a></h3><p>Kerckhoffs：敌手知道算法。安全性在密钥。把 AES 当「军用机密算法」是倒退。</p><p><span class="marginnote">FIPS 197。宽 128/192/256 只改圈数与密钥扩展，块仍是 128。本课不写差分/线性分析的操作程序，只承认设计对着这些分析留余量。</span></p><p><span class="marginnote">常见误区：初学者容易以为「调一次 AES 函数就能加密一个文件」——实际上 AES 只嚼 128 比特（16 字节）一块；「任意长的消息怎么切成块、块之间怎么连」是分组模式（如 GCM）的合同，本课的圈函数一根手指都不碰这件事。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按一圈的四步走一遍数据路径。密钥扩展把主密钥变成轮密钥。强调：AES 本身只处理一块；消息长度、完整性、nonce 是<a href="/cs/block-modes">分组模式</a>的合同，本课不重写 GCM。</p>',12)),(t(),n(o,null,{default:e(()=>[l(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22128%20%E6%AF%94%E7%89%B9%E5%9D%97%22%5D%20--%3E%20SB%5B%22SubBytes%22%5D%0A%20%20SB%20--%3E%20SR%5B%22ShiftRows%22%5D%0A%20%20SR%20--%3E%20MC%5B%22MixColumns%22%5D%0A%20%20MC%20--%3E%20ARK%5B%22AddRoundKey%22%5D%0A%20%20ARK%20--%3E%20OUT%5B%22%E4%B8%8B%E4%B8%80%E5%9C%88%E6%88%96%E5%AF%86%E6%96%87%E5%9D%97%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[E("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,"代换提供非线性，置换与列混合提供扩散，轮密钥打断对称。作为 PRP 候选，它被模式调用：ECB 仍会泄漏相等块——那是模式的锅，不是圈函数「弱了」。实现必须防缓存定时，那是侧信道课的缺口，结构课只点名。",-1)),a[5]||(a[5]=s("p",null,"方法一节的图回答「一圈之内数据怎么走」，下面这张回答另一个问题：整块明文从进到出，密钥扩展与轮数在全景里怎么摆。",-1)),(t(),n(o,null,{default:e(()=>[l(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22%E4%B8%BB%E5%AF%86%E9%92%A5%3A%20128%2F192%2F256%20%E6%AF%94%E7%89%B9%22%5D%20--%3E%20EXP%5B%22%E5%AF%86%E9%92%A5%E6%89%A9%E5%B1%95%3A%20%E5%B1%95%E5%BC%80%E5%87%BA%E5%85%A8%E9%83%A8%E8%BD%AE%E5%AF%86%E9%92%A5%22%5D%0A%20%20PT%5B%22128%20%E6%AF%94%E7%89%B9%E6%98%8E%E6%96%87%E5%9D%97%22%5D%20--%3E%20W%5B%22%E5%88%9D%E5%A7%8B%20AddRoundKey%20(%E7%99%BD%E5%8C%96)%22%5D%0A%20%20W%20--%3E%20R%7B%22%E6%8C%89%E5%AF%86%E9%92%A5%E5%AE%BD%E5%AE%9A%E8%BD%AE%E6%95%B0%3A%2010%2F12%2F14%20%E5%9C%88%22%7D%0A%20%20R%20--%3E%20F%5B%22%E4%B8%80%E5%9C%88%3A%20SubBytes-ShiftRows-MixColumns-AddRoundKey%22%5D%0A%20%20F%20--%3E%7C%22%E5%9C%88%E6%95%B0%E6%9C%AA%E6%BB%A1%22%7C%20F%0A%20%20F%20--%3E%7C%22%E6%9C%80%E5%90%8E%E4%B8%80%E5%9C%88%E7%9C%81%20MixColumns%22%7C%20OUT%5B%22128%20%E6%AF%94%E7%89%B9%E5%AF%86%E6%96%87%E5%9D%97%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p><span class="marginnote">数字实例：AES-128 的密钥空间是 \\(2^{128}\\approx 3.4\\times 10^{38}\\) 个密钥——就算有一台每秒试 \\(10^{18}\\) 个密钥的机器，也要跑约 \\(10^{13}\\) 年，是宇宙年龄的近千倍；「密钥即安全」的分量就在这里。</span></p><p><span class="marginnote">术语翻译：SPN（代换–置换网络）就是用「每轮对全部 128 比特一起做代换再混位置」的手段来做混淆与扩散的事；DES 那种 Feistel 结构则是把块劈成两半、每轮只改一半再交换——同为轮函数思路，但一整块与两半的操作方式不同，下一课对照。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲如何差分分析，不列全部 S 盒代数式当作业。下一课用 Feistel 对照：DES 把块劈成两半，AES 则是 SPN。后课默认：提到分组密码结构，AES 指 FIPS 197 的 SPN。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PRG/PRF 要候选；AES 是 128 比特 SPN。</li><li>圈函数：代换、移位、列混、加轮密钥。</li><li>块密码≠模式；完整性仍在 AEAD。</li><li>Feistel/DES 是下一课的结构对照。</li><li>出处：Daemen and Rijmen, <em>The Design of Rijndael</em>；NIST FIPS 197。</li></ul>',6))])}const C=A(S,[["render",m]]);export{P as __pageData,C as default};
